const contactForm=document.getElementById("contactForm"),contactFormMessage=document.getElementById("contactFormMessage");function showError(e,t){e.classList.add("invalid");e.closest(".form-group").querySelector(".error").textContent=t}function clearError(e){e.classList.remove("invalid");e.closest(".form-group").querySelector(".error").textContent=""}function isValidEmail(e){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)}contactForm.addEventListener("submit",function(e){e.preventDefault();const t=document.getElementById("name"),r=document.getElementById("contactEmail"),s=document.getElementById("message");let o=!0;contactFormMessage.textContent="";contactFormMessage.className="form-message";[t,r,s].forEach(clearError);t.value.trim().length<2&&(showError(t,"Аты-жөніңізді енгізіңіз."),o=!1);isValidEmail(r.value.trim())||(showError(r,"Дұрыс электрондық пошта енгізіңіз."),o=!1);s.value.trim().length<5&&(showError(s,"Хабарламаңызды толығырақ жазыңыз."),o=!1);o&&(contactFormMessage.textContent="Хабарламаңыз жіберілді! Жақын арада сізбен байланысамыз.",contactFormMessage.classList.add("success"),contactForm.reset())});document.querySelectorAll(".contact-form input, .contact-form textarea").forEach(function(e){e.addEventListener("input",function(){clearError(e);contactFormMessage.textContent=""})});
